// bench.js
const fs = require('fs');
const path = require('path');
const {performance} = require('perf_hooks');
const {parseScript} = require('cherow');
const babylon = require('@babel/parser');

// List of filenames (place under ./fixtures/)
const files = [
  'jquery-1.9.1.js',
  'jQuery.Mobile-1.4.2.js',
  'angular-1.6.6.js',
  'react-0.13.3.js',
  'typescript-2.5.js'
];

// How many times to parse each file (to get stable measurements)
const RUNS = 20;

function measure(fn) {
  const start = performance.now();
  fn();
  return performance.now() - start;
}

(async () => {
  console.log('File                           | Cherow (ms) | Babylon (ms)');
  console.log('----------------------------------------------------------');

  for (const file of files) {
    const filePath = path.join(__dirname, 'fixtures', file);
    const code = fs.readFileSync(filePath, 'utf8');

    // Warm up
    parseScript(code);
    babylon.parse(code, {sourceType: 'script', plugins: ['flow']});

    // Measure Cherow
    let totalCherow = 0;
    for (let i = 0; i < RUNS; i++) {
      totalCherow += measure(() => parseScript(code));
    }
    const avgCherow = (totalCherow / RUNS).toFixed(1);

    // Measure Babylon
    let totalBabylon = 0;
    for (let i = 0; i < RUNS; i++) {
      totalBabylon += measure(() =>
        babylon.parse(code, {sourceType: 'script', plugins: ['flow']})
      );
    }
    const avgBabylon = (totalBabylon / RUNS).toFixed(1);

    console.log(
      `${file.padEnd(30)} | ${avgCherow.padStart(10)} | ${avgBabylon.padStart(11)}`
    );
  }
})();
